    {
        return x is BroMakerLib.ICustomHero;
    }
}

using Rewired;
using UM = Utility_Mod.Main;

public static class CompilerAccessUsing
{
    public static void Main()
    {
        ScriptContext.Logger( "Consts=" + typeof( Consts ).AssemblyQualifiedName );
        ScriptContext.Logger( "alias=" + typeof( UM ).FullName + " settings=" + ( UM.settings != null ) );
        ScriptContext.Logger( "io=" + File.Exists( "/nonexistent" ) + " sb=" + new StringBuilder( "ok" ) );
        ScriptContext.Logger( "modui=" + typeof( BroMakerLib.ModUI ).FullName + " unlocks=" + typeof( BroMakerLib.Unlocks.BroUnlockManager ).FullName );
    }
}

namespace CompilerAccessNs
{
    public static class Probe
    {
        public static void Main()
