}

using B = RocketLib.Loggers.Logger;
using static Utility_Mod.Main;

class CompilerAccessAliasBase : B
{
}

public static class CompilerAccessAlias
{
    public static void Main()
    {
        ScriptContext.Logger( "base=" + typeof( CompilerAccessAliasBase ).BaseType.FullName + " made=" + ( new CompilerAccessAliasBase() != null ) + " static=" + ( settings != null ) );
    }
}

public static class CompilerAccessPattern
{
    static bool IsThree( object x )
    {
        return x is 3;
    }

    public static void Main()
    {
        ScriptContext.Logger( "pattern=" + IsThree( 3 ) + "|" + IsThree( 4 ) );
    }
}
